 * Longest common subsequence alignment between one side of a merge and the
 * base it derives from, and the runs of changed lines that alignment leaves
 * uncovered.
 */

/**
 * Build the suffix-LCS length table for `side` against `base`: `table[i][j]`
 * is the length of the longest common subsequence of `side[i:]` and
 * `base[j:]`.
 */
function buildLengthTable(side, base) {
  const n = side.length
  const m = base.length
  const table = Array.from({ length: n + 1 }, () => new Array(m + 1).fill(0))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      if (side[i] === base[j]) {
        table[i][j] = table[i + 1][j + 1] + 1
      } else {
        const skipSide = table[i + 1][j]
        const skipBase = table[i][j + 1]
        table[i][j] = skipSide > skipBase ? skipSide : skipBase
      }
    }
  }
  return table
}

/**
 * Walk `side` and `base` from the start, taking a matched pair whenever the
 * current lines are equal and otherwise advancing whichever side keeps the
 * longest remaining common subsequence available, preferring to advance the
 * base on a tie. Returns the matched `[sideIndex, baseIndex]` pairs in order.
 */
function alignMatches(side, base) {
  const table = buildLengthTable(side, base)
  const matches = []
  let i = 0
  let j = 0
  while (i < side.length && j < base.length) {
    if (side[i] === base[j]) {
      matches.push([i, j])
      i++
      j++
    } else if (table[i + 1][j] > table[i][j + 1]) {
      i++
    } else {
      j++
    }
  }
  return matches
}

/**
 * The runs of `base` this alignment does not cover, each paired with the run
 * of `side` lines that replaces it. An insertion has an empty base run and a
 * deletion has an empty side run.
 */
export function computeChanges(side, base) {
  const matches = alignMatches(side, base)
  const changes = []
  let sideCursor = 0
  let baseCursor = 0
  for (const [si, bi] of matches) {
    if (si > sideCursor || bi > baseCursor) {
      changes.push({ baseStart: baseCursor, baseEnd: bi, sideStart: sideCursor, sideEnd: si })
    }
    sideCursor = si + 1
    baseCursor = bi + 1
  }
  if (sideCursor < side.length || baseCursor < base.length) {
    changes.push({ baseStart: baseCursor, baseEnd: base.length, sideStart: sideCursor, sideEnd: side.length })
  }
  return changes
}
"}

