{"file_path":"src/regions.js","content":"/**
 * Grouping a three-way merge's changes into regions and resolving each one.
 */

import { computeChanges } from './diff.js'

function linesEqual(a, b) {
  return a.length === b.length && a.every((line, index) => line === b[index])
}

/**
 * Merge `mine`'s and `theirs`'s changes into one list ordered by where they
 * start in the base, with mine's changes before theirs's when they tie.
 */
function mergeChangesBySide(mineChanges, theirsChanges) {
  const merged = []
  let i = 0
  let j = 0
  while (i < mineChanges.length && j < theirsChanges.length) {
    if (mineChanges[i].baseStart <= theirsChanges[j].baseStart) {
      merged.push({ ...mineChanges[i], side: 'mine' })
      i++
    } else {
      merged.push({ ...theirsChanges[j], side: 'theirs' })
      j++
    }
  }
  while (i < mineChanges.length) merged.push({ ...mineChanges[i++], side: 'mine' })
  while (j < theirsChanges.length) merged.push({ ...theirsChanges[j++], side: 'theirs' })
  return merged
}

/**
 * Absorb the ordered list of changes into regions: each region starts at its
 * first change's base start and keeps extending its base end while the next
 * change starts at or before that end.
 */
function groupIntoRegions(changes) {
  const regions = []
  let i = 0
  while (i < changes.length) {
    const region = { baseStart: changes[i].baseStart, baseEnd: changes[i].baseEnd, changes: [changes[i]] }
    i++
    while (i < changes.length && changes[i].baseStart <= region.baseEnd) {
      region.baseEnd = Math.max(region.baseEnd, changes[i].baseEnd)
      region.changes.push(changes[i])
      i++
    }
    regions.push(region)
  }
  return regions
}

/**
 * One side's replacement lines for a region: the side's own changes within
 * it, extended to cover the whole region by however far the region's base
 * bounds reach past that side's changes (those extra base lines are stable,
 * so the corresponding side lines are identical to them).
 */
function sideReplacement(region, sideChanges, sideDoc) {
  if (sideChanges.length === 0) return null
  const minBaseStart = Math.min(...sideChanges.map(change => change.baseStart))
  const maxBaseEnd = Math.max(...sideChanges.map(change => change.baseEnd))
  const minSideStart = Math.min(...sideChanges.map(change => change.sideStart))
  const maxSideEnd = Math.max(...sideChanges.map(change => change.sideEnd))
  const start = minSideStart - (minBaseStart - region.baseStart)
  const end = maxSideEnd + (region.baseEnd - maxBaseEnd)
  return sideDoc.slice(start, end)
}

/**
 * Resolve one region into `mine`, `theirs`, `both` (the sides made the same
 * change) or a conflict, given the base lines it spans.
 */
function resolveRegion(region, mine, base, theirs) {
  const baseLines = base.slice(region.baseStart, region.baseEnd)
  if (region.changes.length === 1) {
    const change = region.changes[0]
    const sideDoc = change.side === 'mine' ? mine : theirs
    const lines = sideDoc.slice(change.sideStart, change.sideEnd)
    return { kind: change.side, lines }
  }
  const mineChanges = region.changes.filter(change => change.side === 'mine')
  const theirsChanges = region.changes.filter(change => change.side === 'theirs')
  const mineLines = sideReplacement(region, mineChanges, mine) ?? baseLines
  const theirsLines = sideReplacement(region, theirsChanges, theirs) ?? baseLines
  if (linesEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (linesEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (linesEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * The full ordered list of segments spanning the base document: stable runs
 * kept unchanged and resolved regions, each carrying its resolution.
 */
export function computeSegments(mine, base, theirs) {
  const mineChanges = computeChanges(mine, base)
  const theirsChanges = computeChanges(theirs, base)
