    if (region.baseStart > cursor) {
      segments.push({ type: 'stable', lines: base.slice(cursor, region.baseStart) })
    }
    segments.push({ type: 'region', ...resolveRegion(region, mine, base, theirs) })
    cursor = region.baseEnd
